window.docContents[40].resolve({"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation--Soundness-of-_LPAR_0-___-n_RPAR_-Elimination___-Redux":{"contents":"\n\nRecall the definition optimize0plus from the Slang chapter:def optimize0plus (a : Aexp) : Aexp :=\n  match a with\n  | num   n          => num n\n  | plus  (num 0) e₂ => optimize0plus e₂\n  | plus  e₁      e₂ => plus  (optimize0plus e₁) (optimize0plus e₂)\n  | minus e₁      e₂ => minus (optimize0plus e₁) (optimize0plus e₂)\n  | mult  e₁      e₂ => mult  (optimize0plus e₁) (optimize0plus e₂)\nNote that this function is defined over the old version of Aexps,\nwithout states.Write a new version of this function that deals with variables (by\nleaving them alone), plus analogous ones for Bexps and commands:Aexp.optimize0plus\nBexp.optimize0plus\nCom.optimize0plus\ndef Aexp.optimize0plus (a : Aexp) : Aexp := solution!(\n  match a with\n  | Aexp.num n => Aexp.num n\n  | Aexp.id x => Aexp.id x\n  | (aexp { 0 + ~a₂ }) => Aexp.optimize0plus a₂\n  | (aexp { ~a₁ + ~a₂ }) => (aexp { ~(Aexp.optimize0plus a₁) + ~(Aexp.optimize0plus a₂) })\n  | (aexp { ~a₁ - ~a₂ }) => (aexp { ~(Aexp.optimize0plus a₁) - ~(Aexp.optimize0plus a₂) })\n  | (aexp { ~a₁ * ~a₂ }) => (aexp { ~(Aexp.optimize0plus a₁) * ~(Aexp.optimize0plus a₂) })\n)\n\ndef Bexp.optimize0plus (b : Bexp) : Bexp := solution!(\n  match b with\n  | (bexp { true })        => (bexp { true })\n  | (bexp { false })       => (bexp { false })\n  | (bexp { ~a₁ = ~a₂ })  => (bexp { ~(Aexp.optimize0plus a₁) =  ~(Aexp.optimize0plus a₂) })\n  | (bexp { ~a₁ ≠ ~a₂ })  => (bexp { ~(Aexp.optimize0plus a₁) ≠ ~(Aexp.optimize0plus a₂) })\n  | (bexp { ~a₁ ≤ ~a₂ }) => (bexp { ~(Aexp.optimize0plus a₁) ≤ ~(Aexp.optimize0plus a₂) })\n  | (bexp { ~a₁ > ~a₂ })  => (bexp { ~(Aexp.optimize0plus a₁) >  ~(Aexp.optimize0plus a₂) })\n  | (bexp { ¬ ~b₁ })     => (bexp { ¬ ~(Bexp.optimize0plus b₁) })\n  | (bexp { ~b₁ ∧ ~b₂ }) => (bexp { ~(Bexp.optimize0plus b₁) ∧ ~(Bexp.optimize0plus b₂) })\n)\n\ndef Com.optimize0plus (c : Com) : Com := solution!(\n  match c with\n  | (imp { skip })                     => (imp { skip })\n  | (imp { x := ~a })                  => (imp { x := ~(Aexp.optimize0plus a) })\n  | (imp { c₁ ; c₂ })                  => imp { ~(Com.optimize0plus c₁) ; ~(Com.optimize0plus c₂) }\n  | (imp { if (b) {c₁} else {c₂} }) =>\n      imp { if (~(Bexp.optimize0plus b)) {~(Com.optimize0plus c₁)} else {~(Com.optimize0plus c₂)} }\n  | (imp { while (b) {c₁} })         => imp { while (~(Bexp.optimize0plus b))\n                                          {~(Com.optimize0plus c₁)} }\n)\ntheorem test_optimize0plus :\n    Com.optimize0plus\n       (imp { while (X ≠ 0) { X := 0 + X - 1 } }) =\n    (imp { while (X ≠ 0) { X := X - 1 } }) := by\n  solution!\n    rfl\nProve that these three functions are sound, as we did for\nfoldConstants.  Make sure you use the congruence lemmas in the\nproof for Com.optimize0plus - otherwise it will be long!\nAs with the proofs for foldConstants,\nyou may find the fun_induction tactic helpful here.theorem Aexp.optimize0plus_sound : Aexp.TransSound Aexp.optimize0plus := by\n  solution!\n    intro a st\n    fun_induction Aexp.optimize0plus a <;> simp_all\n\ntheorem Bexp.optimize0plus_sound : Bexp.TransSound Bexp.optimize0plus := by\n  solution!\n    intro b st\n    fun_induction Bexp.optimize0plus b <;>\n      simp_all only [Bexp.eval] <;>\n      rw [Aexp.optimize0plus_sound, Aexp.optimize0plus_sound]\n\ntheorem Com.optimize0plus_sound : Com.TransSound Com.optimize0plus := by\n  solution!\n    intro c\n    induction c with\n    | skip => rfl\n    | asgn x a => apply Com.congruence_asgn; apply Aexp.optimize0plus_sound\n    | seq c₁ c₂ ih₁ ih₂ => apply Com.congruence_seq <;> assumption\n    | cond b c₁ c₂ ih₁ ih₂ =>\n        apply Com.congruence_if <;> try assumption\n        apply Bexp.optimize0plus_sound\n    | whileDo b c ih =>\n        apply Com.congruence_while <;> try assumption\n        apply Bexp.optimize0plus_sound\nFinally, let's define a compound optimizer on commands that first\nfolds constants (using Com.foldConstants) and then eliminates\n0 + n terms (using Com.optimize0plus).def optimizer (c : Com) := Com.optimize0plus (Com.foldConstants c)\nProve that this optimizer is sound.theorem optimizer_sound : Com.TransSound optimizer := by\n  solution!\n    intro c\n    apply Com.equiv_trans\n    · apply Com.optimize0plus_sound\n    · apply Com.foldConstants_sound\n\n\n","context":"Hoare Logic\u0009Equiv: Program Equivalence\u0009Program Transformation","header":"4.3.3. Soundness of (0 + n) Elimination, Redux","id":"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation--Soundness-of-_LPAR_0-___-n_RPAR_-Elimination___-Redux"}});